    try{SharedPreferences prefs=(SharedPreferences)get(real,"mPrefs");((List)get(real,"mChannels")).addAll((List)get(a,"mChannels"));put(real,"mCobraPreviewAutoplayAllowed",false);call(real,"cobraSwitchMode","focus");call(real,"cobraSwitchMode","mobile");assertEquals("focus",prefs.getString("guide_view_mode",""));controller.recreate();real=controller.get();((List)get(real,"mChannels")).addAll((List)get(a,"mChannels"));put(real,"mCobraPreviewAutoplayAllowed",false);call(real,"showCobraPrimaryView");h.f.measure(real,412,915);assertEquals("mobile",get(real,"mCobraGuideStyle"));assertEquals(false,call(real,"cobraProPlayerSportsEnabled"));assertNull(get(real,"mCobraProHeroUi"));}finally{controller.pause().stop().destroy();}
