  @Test public void fourCompleteBroadcastRowsAtEveryFoldAndSmallWindowWithInsets()throws Exception{
    context("pro_sports");fullscreen(false);
    for(int[] size:new int[][]{{412,915},{915,412},{720,840},{840,720},{280,280}})for(int count:new int[]{1,3,4,8}){
      RuntimeEnvironment.setQualifiers("w"+size[0]+"dp-h"+size[1]+"dp-"+(size[0]>size[1]?"land":"port")+"-mdpi");directChoices(count);
      WindowInsets insets=new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),android.graphics.Insets.of(8,24,8,24)).setInsetsIgnoringVisibility(WindowInsets.Type.systemBars(),android.graphics.Insets.of(8,24,8,24)).build();View sheet=(View)get(a,"mCobraActionSheet");sheet.dispatchApplyWindowInsets(insets);h.f.measure(a,size[0],size[1]);
      assertEquals(24,get(sheet,"safeTop"));assertEquals(24,get(sheet,"safeBottom"));assertEquals(false,get(sheet,"geometryBlocked"));ListView rows=(ListView)sheet.findViewWithTag("cobra_broadcast_channels");assertEquals(count,rows.getAdapter().getCount());int complete=0;for(int i=0;i<rows.getChildCount();i++){View row=rows.getChildAt(i);Rect bounds=new Rect();assertTrue(row.getGlobalVisibleRect(bounds));assertTrue(row.getHeight()>=48);if(bounds.height()==row.getHeight())complete++;}assertTrue(Arrays.toString(size)+" count="+count+" complete="+complete,complete>=Math.min(4,count));if(count>4){rows.setSelection(count-1);h.f.measure(a,size[0],size[1]);assertEquals(count-1,rows.getLastVisiblePosition());}call(a,"closeCobraActionSheet");
    }
  }
