  @Test public void proHeaderUsesThemeTokensAndRetainsOriginalActionsAcrossVariants()throws Exception{context("pro_non_sports");for(String appearance:new String[]{"dark","light","oled","system"})for(String ambient:new String[]{"off","subtle","immersive"})for(boolean night:new boolean[]{false,true}){h.prefs.edit().putString("cobra_appearance_mode",appearance).putString(CobraPresentationEffects.AMBIENT,ambient).commit();Configuration config=new Configuration(a.getResources().getConfiguration());config.uiMode=(config.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(night?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);a.getResources().updateConfiguration(config,a.getResources().getDisplayMetrics());call(a,"cobraRestyleGuide");measure();TextView title=(TextView)get(a,"mCobraModeTitle"),sub=(TextView)get(a,"mCobraModeSub");assertEquals(call(a,"cobraModeColor","text"),title.getCurrentTextColor());assertEquals(call(a,"cobraModeColor","muted"),sub.getCurrentTextColor());ViewGroup header=(ViewGroup)get(a,"mCobraModeToolbar");assertNotNull(header.getBackground());assertEquals(4,header.getChildCount());assertNotNull(h.f.description(header,"Open Cobra navigation"));assertNotNull(h.f.description(header,"Choose view mode"));assertNotNull(header.findViewWithTag("cobra_mode_visuals"));}}
  @Test public void channelsCarryExistingRequestedVolumeWithoutChangingSystemVolume()throws Exception{context("mobile");fullscreen(false);Object audio=call(a,"cobraMediaAudioState",h.player);put(audio,"volume",.4f);h.state.volume=.4f;android.media.AudioManager manager=(android.media.AudioManager)a.getSystemService(android.content.Context.AUDIO_SERVICE);int before=manager.getStreamVolume(android.media.AudioManager.STREAM_MUSIC);channels();rowClick("All");ExoPlayer replacement=(ExoPlayer)get(a,"mPlayer");assertEquals(.4f,replacement.getVolume(),0);assertEquals(.4f,(Float)get(call(a,"cobraMediaAudioState",replacement),"volume"),0);assertEquals(before,manager.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));}
  @Test public void transientSuppressionDoesNotBecomeUserMuteDuringChannelsTune()throws Exception{for(boolean callMode:new boolean[]{false,true}){reset();context("mobile");fullscreen(false);android.media.AudioManager manager=(android.media.AudioManager)a.getSystemService(android.content.Context.AUDIO_SERVICE);call(a,"cobraClaimAudioFocus",h.player);if(callMode){manager.setMode(android.media.AudioManager.MODE_IN_COMMUNICATION);call(a,"cobraHandleAudioMode",h.player,get(a,"mCobraAudioFocusGeneration"),android.media.AudioManager.MODE_IN_COMMUNICATION);}else call(a,"cobraHandleAudioFocus",h.player,get(a,"mCobraAudioFocusGeneration"),android.media.AudioManager.AUDIOFOCUS_LOSS_TRANSIENT);assertEquals(false,get(call(a,"cobraMediaAudioState",h.player),"userMuted"));assertEquals(0f,h.state.volume,0);channels();rowClick("All");ExoPlayer replacement=(ExoPlayer)get(a,"mPlayer");assertEquals(false,get(call(a,"cobraMediaAudioState",replacement),"userMuted"));assertNull(get(a,"mCobraChannelsTuneMuted"));manager.setMode(android.media.AudioManager.MODE_NORMAL);call(a,"cobraHandleAudioMode",replacement,get(a,"mCobraAudioFocusGeneration"),android.media.AudioManager.MODE_NORMAL);call(a,"cobraHandleAudioFocus",replacement,get(a,"mCobraAudioFocusGeneration"),android.media.AudioManager.AUDIOFOCUS_GAIN);assertEquals(false,get(call(a,"cobraMediaAudioState",replacement),"userMuted"));}}
  @Test public void upcomingAndNullSummaryRenderHonestUnavailableState()throws Exception{context("pro_sports");put(game,"state","pre");put(game,"timeConfirmed",false);put(game,"startMs",System.currentTimeMillis()+3600000L);repository(null);call(a,"showCobraSportsStats",game);((CobraNavigationUiTest.PendingIo)get(a,"mIo")).drain();h.f.frames(3);String text=h.text((View)get(a,"mCobraActionSheet"));assertTrue(text.contains("Time TBA"));assertTrue(text.contains("Statistics are unavailable right now."));assertFalse(text.contains("TEAM STAT"));assertFalse(text.contains("11:37"));}
  @Test public void channelsMuteTransferAlsoCoversSynchronousLiveRewindProxyConstruction()throws Exception{for(boolean muted:new boolean[]{true,false}){reset();context("mobile");fullscreen(muted);h.prefs.edit().putBoolean("cobra_live_rewind_enabled",true).commit();for(int i=1;i<8;i++)put(h.channel(i),"primaryUrl","http://127.0.0.1:9/live.ts");assertEquals(true,call(a,"cobraShouldUseLocalTimeshift",h.channel(1),get(h.channel(1),"primaryUrl")));channels();rowClick("All");try{ExoPlayer replacement=(ExoPlayer)get(a,"mPlayer");assertSame(replacement,get(a,"mCobraTimeshiftProxyPlayer"));assertNotNull(get(a,"mCobraTimeshiftSession"));assertEquals(muted?0f:1f,replacement.getVolume(),0);assertEquals(muted,get(call(a,"cobraMediaAudioState",replacement),"userMuted"));assertNull(get(a,"mCobraChannelsTuneMuted"));}finally{call(a,"closePlayer");}}}
  @Test public void nonSportsProChannelsSportsCategoryAlsoPreservesUserMute()throws Exception{for(boolean muted:new boolean[]{false,true}){reset();context("pro_non_sports");game=h.addLiveGameForChannel(1);fullscreen(muted);channels();click(drawer(),"Sports");measure();assertTrue(list().getChildAt(0).performClick());((CobraNavigationUiTest.PendingIo)get(a,"mIo")).drain();h.f.frames(3);assertSame(h.channel(1),get(a,"mPlaying"));assertEquals(muted?0f:1f,((ExoPlayer)get(a,"mPlayer")).getVolume(),0);assertNull(chrome().findViewWithTag("cobra_fullscreen_stats"));}}
